     1	{% extends "base.html" %}
     2	{% block title %}Статус — Metacritic digest{% endblock %}
     3	
     4	{% block head %}
     5	  <script src="https://unpkg.com/htmx-ext-sse@2.2.4/sse.js"></script>
     6	{% endblock %}
     7	
     8	{% block content %}
     9	  <h1>Статус воркера</h1>
    10	
    11	  {# Кнопка бьёт в ту же ручку, что и планировщик; токен подставлен сервером
    12	     (OQ-8). Ответ намеренно не подменяет разметку: что заход начался, видно в
    13	     ленте событий ниже, а не по перерисованному куску страницы. #}
    14	  <div class="run-row">
    15	    <button id="run-btn" hx-post="/admin/run" hx-swap="none"
    16	            hx-headers='{"X-Admin-Token": {{ admin_token | tojson }}}'>
    17	      Запустить обработку сейчас
    18	    </button>
    19	    <span id="run-result" class="muted"></span>
    20	  </div>
    21	
    22	  {# hx-ext на общей обёртке: внутри неё htmx сам держит EventSource и
    23	     переподключается при обрыве — своего JS для этого не нужно. #}
    24	  <div hx-ext="sse" sse-connect="/events">
    25	    <div id="panel" sse-swap="panel">{% include "_status_panel.html" %}</div>
    26	
    27	    <h2>Лента событий</h2>
    28	    <ul id="feed" sse-swap="feed" hx-swap="afterbegin">
    29	      {% for event in events %}{% include "_status_event.html" %}{% endfor %}
    30	      {% if not events %}<li class="muted">Событий пока не было: буфер живёт в памяти и очищается при рестарте.</li>{% endif %}
    31	    </ul>
    32	  </div>
    33	
    34	  <h2>Последние заходы</h2>
    35	  {# Журнал читается из БД при открытии страницы: строка `runs` меняется дважды
    36	     за заход, realtime здесь ничего не добавит — обновляется перезагрузкой. #}
    37	  <table class="runs">
    38	    <thead>
    39	      <tr><th>#</th><th>День</th><th>Запуск</th><th>Статус</th><th>Фаза</th>
    40	          <th>Игр</th><th>LLM</th><th>Начат</th><th>Длительность</th></tr>
    41	    </thead>
    42	    <tbody>
    43	      {% for run in runs %}
    44	        <tr class="run-{{ run.status }}">
    45	          <td>{{ run.id }}</td>
    46	          <td>{{ run.day }}</td>
    47	          <td>{{ 'вручную' if run.trigger == 'manual' else 'план' }}</td>
    48	          <td>{{ run.status }}{% if run.error %}<div class="muted err">{{ run.error }}</div>{% endif %}</td>
    49	          <td>{{ run.phase or '—' }}</td>
    50	          <td>{{ run.games_ok }}/{{ run.games_claimed }}{% if run.games_failed %}, ош. {{ run.games_failed }}{% endif %}</td>
    51	          <td>{{ run.llm_calls }}{% if run.llm_failures %} / отказов {{ run.llm_failures }}{% endif %}</td>
    52	          <td>{{ run.started_at.strftime('%d.%m %H:%M:%S') }}</td>
    53	          <td>{{ '%.0f с' | format((run.finished_at - run.started_at).total_seconds()) if run.finished_at else '—' }}</td>
    54	        </tr>
    55	      {% else %}
    56	        <tr><td colspan="9" class="muted">Заходов ещё не было.</td></tr>
    57	      {% endfor %}
    58	    </tbody>
    59	  </table>
    60	
    61	  <script>
    62	    // htmx не подменяет ответы с кодом 4xx, а 409 «заход уже идёт» и 401 —
    63	    // это нормальные ответы кнопки, и показать их надо. Дешевле трёх строк
    64	    // здесь только целое расширение response-targets.
    65	    document.body.addEventListener('htmx:afterRequest', (e) => {
    66	      if (e.detail.pathInfo.requestPath !== '/admin/run') return;
    67	      const codes = {202: 'Заход запущен', 409: 'Заход уже идёт', 401: 'Неверный admin-токен'};
    68	      document.getElementById('run-result').textContent =
    69	        codes[e.detail.xhr.status] || ('Ошибка ' + e.detail.xhr.status);
    70	    });
    71	  </script>
    72	
    73	  <style>
    74	    h2 { font-size:16px; margin:26px 0 10px; }
    75	    .run-row { display:flex; align-items:center; gap:12px; margin:0 0 20px; }
    76	    #run-btn { font:inherit; padding:8px 14px; border-radius:8px; cursor:pointer;
    77	               border:1px solid var(--line); background:var(--card); color:var(--fg); }
    78	    #run-btn:hover { border-color:var(--muted); }
    79	    .tiles { display:grid; gap:12px; grid-template-columns:repeat(auto-fit, minmax(170px, 1fr)); }
    80	    .tile { background:var(--card); border:1px solid var(--line); border-radius:10px;
    81	            padding:10px 12px; display:flex; flex-direction:column; gap:2px; min-width:0; }
    82	    .tile .label { font-size:12px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); }
    83	    .tile b { font-size:16px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
    84	    .tile b.run { color:#2e9e5b; }
    85	    .tile .muted { font-size:13px; }
    86	    #feed { list-style:none; margin:0; padding:0; max-height:420px; overflow-y:auto;
    87	            border:1px solid var(--line); border-radius:10px; background:var(--card); }
    88	    .ev { display:flex; gap:8px; align-items:baseline; padding:5px 12px; font-size:14px;
    89	          border-bottom:1px solid var(--line); }
    90	    .ev:last-child { border-bottom:none; }
    91	    .ev time { color:var(--muted); font-variant-numeric:tabular-nums; font-size:13px; }
    92	    .ev-run_started, .ev-run_finished { background:color-mix(in srgb, var(--line) 40%, transparent); }
    93	    .mark.ok { color:#2e9e5b; }
    94	    .mark.fail, .fail { color:#c8443c; }
    95	    .runs { border-collapse:collapse; width:100%; font-size:14px; }
    96	    .runs th, .runs td { text-align:left; padding:6px 10px; border-bottom:1px solid var(--line);
    97	                         vertical-align:top; }
    98	    .runs th { font-size:12px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); }
    99	    .runs .err { max-width:340px; overflow-wrap:anywhere; }
   100	  </style>
   101	{% endblock %}

