   174	            {{ letsplay.video_title or 'Смотреть на YouTube' }}</a>
   175	          <span class="muted">
   176	            {%- if letsplay.channel %} · {{ letsplay.channel }}{% endif %}
   177	            {%- if letsplay.view_count %} · {{ letsplay.view_count|views }} просмотров{% endif %}
   178	          </span>
   179	        </p>
   180	        {% if letsplay.retelling %}
   181	          {# Пересказ длинный и машинный — по умолчанию свёрнут: в карточке
   182	             главное заключение, а пересказ нужен, чтобы его проверить. #}
   183	          <details class="retelling">
   184	            <summary>Пересказ ролика</summary>
   185	            <div class="retelling-text">{{ letsplay.retelling }}</div>
   186	          </details>
   187	        {% endif %}
   188	      </section>
   189	    {% endif %}
