   226	    .summary .origin { margin:10px 0 0; font-size:12px; }
   227	    /* .game .cover задан под обложку карточки — в списке похожих её размер свой. */
   228	    .similar { display:flex; gap:16px; flex-wrap:wrap; list-style:none; margin:0; padding:0; }
