content.content:
{# Одна строка ленты. Тот же шаблон отдаёт SSE-кадр `feed`, поэтому события,
   пришедшие до открытия страницы (из буфера шины), и события после неё
   выглядят одинаково. #}
{% set p = event.payload %}
<li class="ev ev-{{ event.kind }}">
  <time>{{ event.ts.strftime('%H:%M:%S') }}</time>
  {%- if event.kind == 'run_started' %}
    <b>Заход #{{ p.run_id }} начат</b> — {{ 'вручную' if p.trigger == 'manual' else 'по расписанию' }}
  {%- elif event.kind == 'counters' %}
    Батч выбран: {{ p.claimed }} игр, фаза {{ p.phase }}, страниц {{ p.pages }}
  {%- elif event.kind == 'game_started' %}
    <span class="mark">→</span> {{ p.title or p.slug }}
  {%- elif event.kind == 'game_done' %}
    <span class="mark ok">✓</span> {{ p.title or p.slug }}
  {%- elif event.kind == 'game_failed' %}
    <span class="mark fail">✗</span> {{ p.title or p.slug }} — {{ p.error }}
  {%- elif event.kind == 'llm_call' %}
    <span class="mark">≈</span> резюме: вызовов {{ p.calls }}{% if p.failures %}, неудачных {{ p.failures }}{% endif %} — {{ p.title or p.slug }}
  {%- elif event.kind == 'letsplay' %}
    <span class="mark">▶</span> летсплей: {{ p.status }} — {{ p.title or p.slug }}
  {%- elif event.kind == 'run_finished' %}
    <b>Заход {% if p.run_id %}#{{ p.run_id }} {% endif %}завершён</b> — {{ p.status }}
    {%- if p.status not in ('skipped_locked',) %}, ok {{ p.ok }}, ошибок {{ p.failed }}{% endif %}
    {%- if p.error %} <span class="fail">{{ p.error }}</span>{% endif %}
  {%- else %}
    {{ event.kind }} {{ p }}
  {%- endif %}
</li>
{# Блок счётчиков. Рендерится и в первичной странице, и в SSE-кадре `panel`:
   разметка одна, поэтому обновление не может разойтись с первым рендером. #}
<div class="tiles">
  <div class="tile">
    <span class="label">Воркер</span>
    <b class="{{ 'run' if state.status == 'running' else '' }}">
      {{ 'идёт заход' if state.status == 'running' else 'простой' }}
      {%- if state.run_id %} #{{ state.run_id }}{% endif %}
    </b>
    <span class="muted">{{ 'вручную' if state.trigger == 'manual' else 'по расписанию' if state.trigger else '—' }}</span>
  </div>
  <div class="tile">
    <span class="label">Сейчас</span>
    <b>{{ state.current_game or '—' }}</b>
    <span class="muted">в работе {{ state.in_flight | length }}</span>
  </div>
  <div class="tile">
    <span class="label">День (UTC)</span>
    <b>{{ state.day }}</b>
    <span class="muted">фаза {{ state.phase }}, offset {{ state.browse_offset }}</span>
  </div>
  <div class="tile">
    <span class="label">Игр за сегодня</span>
    <b>{{ state.ok }} <span class="muted">/ {{ state.claimed }}</span></b>
    <span class="muted">ошибок {{ state.failed }}, в работе {{ state.in_progress }}</span>
  </div>
  <div class="tile">
    <span class="label">Вызовов LLM</span>
    <b>{{ state.llm_calls }}</b>
    <span class="muted">
      {%- if state.llm_failures %}неудачных {{ state.llm_failures }}{% else %}без отказов{% endif -%}
    </span>
  </div>
  <div class="tile">
    <span class="label">Последнее событие</span>
    <b>{{ state.last_event_at.strftime('%H:%M:%S') if state.last_event_at else '—' }}</b>
    <span class="muted">UTC</span>
  </div>
</div>
